"use client";

import { useRef, useState, useEffect, useCallback } from "react";
import { AudioStreamer } from "@/lib/audioStreamer";

export default function InterviewPage() {
  const [recording, setRecording] = useState(false);
  const [paused, setPaused] = useState(false);
  const [transcript, setTranscript] = useState("");
  const streamerRef = useRef<AudioStreamer | null>(null);

  const makeWsUrl = useCallback((): string => {
    return "ws://127.0.0.1:8000/ws";
  }, []);

  useEffect(() => {
    return () => {
      try { streamerRef.current?.stop(); } catch {}
      streamerRef.current = null;
    };
  }, []);

  const start = useCallback(async () => {
    if (recording && !paused) return;
    try {
      const streamer = new AudioStreamer();
      streamer.onText = (text: string) =>
        setTranscript((prev) => (prev ? `${prev} ${text}` : text));
      streamerRef.current = streamer;

      const wsUrl = makeWsUrl();
      await streamer.start({
        wsUrl,
        inRate: 16000,
        outRate: 24000,
        chunkMs: 40,
        transport: "binary",
        debug: false,
      });

      setRecording(true);
      setPaused(false);
    } catch (e) {
      console.error("Start error:", e);
      try { streamerRef.current?.stop(); } catch {}
      streamerRef.current = null;
      setRecording(false);
      setPaused(false);
    }
  }, [recording, paused, makeWsUrl]);

  const stop = useCallback(() => {
    if (!recording && !paused) return;
    try { streamerRef.current?.stop(); } catch {}
    streamerRef.current = null;
    setRecording(false);
    setPaused(false);
  }, [recording, paused]);

  const pause = useCallback(() => {
    if (!recording || paused) return;
    try { streamerRef.current?.stop(); } catch {}
    streamerRef.current = null;
    setPaused(true);
  }, [recording, paused]);

  const resume = useCallback(async () => {
    if (!paused) return;
    try {
      const streamer = new AudioStreamer();
      streamer.onText = (text: string) =>
        setTranscript((prev) => (prev ? `${prev} ${text}` : text));
      streamerRef.current = streamer;

      const wsUrl = makeWsUrl();
      await streamer.start({
        wsUrl,
        inRate: 16000,
        outRate: 24000,
        chunkMs: 40,
        transport: "binary",
        debug: false,
      });

      setPaused(false);
      setRecording(true);
    } catch (e) {
      console.error("Resume error:", e);
      try { streamerRef.current?.stop(); } catch {}
      streamerRef.current = null;
      setPaused(true);
      setRecording(false);
    }
  }, [paused, makeWsUrl]);

  return (
    <main className="container mx-auto px-4 py-16">
      <h2 className="text-3xl font-bold mb-4">Buổi phỏng vấn mô phỏng</h2>

      {!recording && (
        <button onClick={start} className="bg-green-500 text-white py-2 px-4 rounded">
          Bắt đầu ghi âm
        </button>
      )}

      {recording && !paused && (
        <div className="flex gap-4">
          <button onClick={pause} className="bg-yellow-500 text-white py-2 px-4 rounded">
            Tạm dừng
          </button>
          <button onClick={stop} className="bg-red-500 text-white py-2 px-4 rounded">
            Dừng ghi
          </button>
        </div>
      )}

      {paused && (
        <div className="flex gap-4">
          <button onClick={resume} className="bg-blue-500 text-white py-2 px-4 rounded">
            Tiếp tục
          </button>
          <button onClick={stop} className="bg-red-500 text-white py-2 px-4 rounded">
            Dừng ghi
          </button>
        </div>
      )}

      <div className="mt-10">
        <h3 className="text-xl font-semibold mb-2">Bạn vừa nói:</h3>
        <p className="bg-gray-100 p-4 rounded">{transcript || "Chưa có nội dung"}</p>
      </div>
    </main>
  );
}